// Extract incoming data and prepare for agent
const incomingData = $input.first().json;

// Handle different webhook formats
let contactId, phoneNumber, message, contactName, sessionId;

if (incomingData.contact_id || incomingData.contactId) {
  contactId = incomingData.contact_id || incomingData.contactId;
  phoneNumber = incomingData.phone || incomingData.from;
  message = incomingData.message || incomingData.body;
  contactName = incomingData.contact_name || incomingData.name;
} else if (incomingData.From && incomingData.Body) {
  phoneNumber = incomingData.From;
  message = incomingData.Body;
  contactId = phoneNumber.replace(/\+|\s|-/g, '');
  contactName = incomingData.ProfileName || 'Unknown';
}

// Create consistent session ID for the agent
sessionId = contactId || phoneNumber.replace(/\+|\s|-/g, '');

return {
  contactId,
  phoneNumber, 
  message,
  contactName,
  sessionId,
  timestamp: new Date().toISOString(),
  // Format for LangChain agent
  input: message,
  chat_input: message
};

// Build enhanced context for the AI agent
const agentInput = $('Prepare Agent Input').first().json;
const conversationHistory = $('Get Conversation History').first().json || [];
const contactContext = $('Get Contact Context').first().json || [];
const dynamicPrompt = $('Get Dynamic Prompt').first().json || [];

// Build conversation history for context
let historyContext = "";
if (conversationHistory.length > 0) {
  historyContext = "\n\nPREVIOUS CONVERSATION:\n" + conversationHistory.map((conv, index) => {
    return `${index + 1}. Human: ${conv.user_message}\n   AI: ${conv.ai_response} [Stage: ${conv.conversation_stage}, Score: ${conv.engagement_score}]`;
  }).reverse().join('\n');
}

// Extract contact information
let contactInfo = "New contact - no previous data";
if (contactContext.length > 0) {
  const ctx = contactContext[0];
  contactInfo = `CONTACT PROFILE:
- Name: ${ctx.name || agentInput.contactName}
- Business: ${ctx.business_type || 'Unknown'}
- Current Stage: ${ctx.current_stage || 'discovery'}
- Lead Score: ${ctx.lead_score || 5}/10
- Total Messages: ${ctx.total_messages || 0}
- Pain Points: ${ctx.pain_points || 'Not identified yet'}`;
}

// Get the best performing prompt for current stage
let systemPrompt = '';
if (dynamicPrompt.length > 0) {
  systemPrompt = dynamicPrompt[0].prompt_content;
} else {
  // Fallback to default Konversly prompt
  systemPrompt = `# Konversly AI Setter – Advanced SMS Agent

## CORE MISSION
You are an AI sales setter for Konversly. Your job is to warm leads and book qualified prospects for sales calls. You're having a TEXT CONVERSATION, so keep responses casual and under 1000 characters.

## CONVERSATION STAGES & OBJECTIVES

### DISCOVERY STAGE
- Identify what kind of business they run
- Uncover their biggest lead generation challenges
- Build rapport through active listening
- Echo their pain points to show understanding

### EDUCATION STAGE  
- Present Konversly as the solution to their specific problem
- Share relevant results and social proof
- Create urgency around their pain point
- Bridge to booking request

### BOOKING STAGE
- Make direct ask for Zoom call
- Handle objections with NEPQ methodology
- Send booking link: konversly.com/book
- Create urgency with limited availability

## RESPONSE RULES
- Always echo part of their answer before moving forward
- Ask ONE question at a time
- No corporate speak - be conversational
- If they ask "is that what you do?" answer directly then bridge to next stage
- Never jump stages until current objectives are complete`;
}

// Combine everything into enhanced system message
const enhancedSystemMessage = `${systemPrompt}

${contactInfo}
${historyContext}

## CURRENT MESSAGE TO RESPOND TO
Human: ${agentInput.message}

## INSTRUCTIONS
Respond naturally according to your stage objectives. Keep under 1000 characters. Remember the conversation context above.`;

return {
  ...agentInput,
  enhancedSystemMessage,
  hasHistory: conversationHistory.length > 0,
  currentStage: contactContext.length > 0 ? contactContext[0].current_stage : 'discovery',
  leadScore: contactContext.length > 0 ? contactContext[0].lead_score : 5
};

// Analyze the AI agent's response
const agentResponse = $json.response || $json.text || $json.output;
const contextData = $('Build Enhanced Context').first().json;

// Determine conversation stage based on response content
let nextStage = contextData.currentStage;
let responseType = 'continue';

// Stage progression logic
if (agentResponse.toLowerCase().includes('what kind of business')) {
  responseType = 'business_question';
  nextStage = 'discovery';
} else if (agentResponse.toLowerCase().includes('biggest challenge')) {
  responseType = 'challenge_question'; 
  nextStage = 'discovery';
} else if (agentResponse.toLowerCase().includes('we help') || agentResponse.toLowerCase().includes('konversly')) {
  responseType = 'pitch';
  nextStage = 'education';
} else if (agentResponse.toLowerCase().includes('open to a quick zoom') || agentResponse.toLowerCase().includes('book')) {
  responseType = 'booking_request';
  nextStage = 'booking';
} else if (agentResponse.toLowerCase().includes('konversly.com/book')) {
  responseType = 'booking_link_sent';
  nextStage = 'booking';
}

// Calculate engagement score
let engagementScore = 5;
if (agentResponse.includes('?')) engagementScore += 1;
if (agentResponse.length > 200 && agentResponse.length < 800) engagementScore += 1;
if (agentResponse.toLowerCase().includes('got it') || agentResponse.toLowerCase().includes('makes sense')) engagementScore += 1;
if (agentResponse.includes('konversly.com')) engagementScore += 2;
if (agentResponse.length > 1000) engagementScore -= 2; // Too long

// Detect objection handling
let hasObjectionHandling = false;
if (agentResponse.toLowerCase().includes('totally fair') || 
    agentResponse.toLowerCase().includes('makes sense') ||
    agentResponse.toLowerCase().includes('i understand')) {
  hasObjectionHandling = true;
  engagementScore += 1;
}

return {
  aiResponse: agentResponse,
  nextStage,
  responseType,
  engagementScore,
  characterCount: agentResponse.length,
  hasQuestion: agentResponse.includes('?'),
  hasBookingLink: agentResponse.includes('konversly.com'),
  hasObjectionHandling,
  timestamp: new Date().toISOString()
};

